const HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>THE PACT — Two-Player Life RPG</title>\n<meta name=\"theme-color\" content=\"#101916\">\n<style>\n:root{--bg:#0c1512;--panel:#16221d;--panel2:#1b2922;--border:#314438;--text:#f4f2e7;--muted:#b7c0ae;--cream:#f5de9a;--lime:#c8f174;--rose:#ffbaa5;--blue:#9ed8e3;--shadow:0 14px 42px #0004}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(circle at 90% 0,#253e2c 0,transparent 32%),radial-gradient(circle at -20% 34%,#1c3331 0,transparent 35%),var(--bg);color:var(--text);font:15px/1.45 system-ui,-apple-system,\"Segoe UI\",sans-serif;min-height:100vh}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--lime);outline-offset:2px}a{color:var(--lime)}.shell{width:min(1080px,100%);padding:24px 18px 80px;margin:0 auto}.tiny{font-size:11px;text-transform:uppercase;font-weight:800;letter-spacing:.14em;color:var(--lime)}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(34px,7vw,66px);letter-spacing:-.065em;line-height:.98;margin:9px 0}h2{font-size:24px;letter-spacing:-.03em;margin-bottom:12px}h3{font-size:17px;margin:0 0 8px}.muted{color:var(--muted)}.subtle{font-size:13px;color:var(--muted)}.hero{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:20px;padding:12px 0 22px}.hero p{max-width:620px;margin-bottom:0;color:var(--muted)}.mark{display:inline-flex;align-items:center;justify-content:center;width:58px;height:58px;border:1.5px solid var(--lime);color:var(--lime);border-radius:18px;font-size:37px;transform:rotate(-7deg)}.status{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0 12px}.pill{border:1px solid var(--border);border-radius:999px;color:var(--muted);padding:7px 11px;font-size:12px}.button{border:1px solid var(--border);background:#25362c;color:var(--text);border-radius:11px;padding:10px 14px;font-weight:700;min-height:40px}.button:hover:not(:disabled){background:#334a39}.button.primary{background:var(--lime);color:#203015;border-color:var(--lime)}.button.primary:hover{background:#dbffa2}.button.ghost{background:transparent}.button.small{font-size:12px;min-height:32px;padding:6px 9px;border-radius:8px}.button.warn{color:var(--rose)}.row{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.between{justify-content:space-between}.card{border:1px solid var(--border);background:linear-gradient(155deg,#1c2d23,#131f19);border-radius:18px;padding:18px;box-shadow:var(--shadow)}.score-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}.player{padding:20px;min-width:0}.player.active{border-color:var(--lime)}.player.paula.active{border-color:var(--rose)}.player-title{display:flex;align-items:center;gap:10px}.avatar{height:37px;width:37px;border-radius:50%;display:grid;place-items:center;background:#3b5a37;color:var(--lime);font-size:21px;font-weight:800}.paula .avatar{background:#623c3c;color:var(--rose)}.score{font-size:clamp(32px,6vw,50px);font-weight:900;letter-spacing:-.07em;line-height:1.15;margin:12px 0 2px}.score span{font-size:15px;letter-spacing:0;font-weight:500;color:var(--muted)}.bar{width:100%;height:9px;background:#3d443c;border-radius:999px;overflow:hidden;margin:11px 0}.fill{height:100%;background:var(--lime);border-radius:999px;transition:width .2s}.paula .fill{background:var(--rose)}.boss{margin:13px 0 20px;display:grid;grid-template-columns:1fr auto;gap:14px;align-items:center}.boss-title{font-size:20px;font-weight:850;letter-spacing:-.03em}.boss .bar{height:12px}.tabs{display:flex;gap:7px;border-bottom:1px solid var(--border);padding-bottom:9px;margin:23px 0 16px;overflow:auto}.tab{background:transparent;color:var(--muted);border:1px solid transparent;border-radius:9px;padding:10px 14px;font-weight:800;white-space:nowrap}.tab[aria-selected=true]{background:var(--lime);color:#23321c}.layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:16px;align-items:start}.stack{display:flex;flex-direction:column;gap:13px}.field{display:flex;flex-direction:column;gap:6px;color:var(--muted);font-size:12px;font-weight:750;letter-spacing:.02em}.field input,.field select,.field textarea{width:100%;border:1px solid #4b6051;border-radius:10px;background:#0b1611;color:var(--text);padding:12px;min-height:43px}.field textarea{resize:vertical;min-height:70px}.field input::placeholder,.field textarea::placeholder{color:#829085}.cols2{display:grid;grid-template-columns:1fr 1fr;gap:10px}.cols3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.section-head h2{margin-bottom:0}.quest{padding:15px}.quest-head{display:flex;justify-content:space-between;gap:9px;align-items:flex-start}.quest-title{font-size:17px;font-weight:800;margin:5px 0 3px;overflow-wrap:anywhere}.tags{display:flex;flex-wrap:wrap;gap:6px}.tag{font-size:11px;border:1px solid #50634c;color:#d5e9bc;border-radius:999px;padding:3px 8px}.tag.rose{color:var(--rose);border-color:#855c54}.tag.blue{color:var(--blue);border-color:#507d85}.tag.gold{color:var(--cream);border-color:#6c633d}.quest-actions{display:flex;flex-wrap:wrap;gap:6px;padding-top:13px}.quest p{margin:7px 0 0}.empty{padding:38px 18px;text-align:center;border:1px dashed #596453;border-radius:17px;color:var(--muted)}.empty strong{display:block;color:var(--text);margin-bottom:7px}.filterbar{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:11px}.filter{border:1px solid var(--border);background:none;border-radius:9px;color:var(--muted);padding:6px 10px;font-size:12px}.filter.selected{background:#31513c;color:#fff}.small-note{font-size:12px;color:var(--muted);line-height:1.5}.feed{display:flex;flex-direction:column;gap:10px}.feed-item{border-left:3px solid var(--border);padding:4px 0 5px 11px;font-size:13px}.feed-item strong{color:var(--cream)}.feed-time{font-size:11px;color:#9cae9e;margin-top:4px}.hidden{display:none!important}.notice{border:1px solid #66683a;background:#333522;border-radius:12px;padding:12px;color:#f5eab7;font-size:13px}.big-figure{font-size:30px;font-weight:850;letter-spacing:-.045em}.stake-hero{border:1px dashed #866e45;background:linear-gradient(130deg,#352b22,#1a251c);border-radius:17px;padding:20px;margin-bottom:15px}.pair{display:flex;align-items:center;gap:8px}.stamp{font-size:12px;padding:7px 11px;border-radius:100px;border:1px solid #777;color:var(--muted)}.stamp.ok{border-color:var(--lime);color:var(--lime)}.topbar{display:flex;align-items:center;justify-content:space-between;gap:8px}.footer{border-top:1px solid var(--border);margin-top:28px;padding-top:17px}.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#e5f9b4;color:#253520;padding:12px 20px;border-radius:12px;font-weight:800;box-shadow:var(--shadow);z-index:9;max-width:95vw}.hint{font-size:12px;background:#202d25;border:1px solid var(--border);border-radius:11px;padding:10px;color:#dce9d0}.quest-actions button{flex-shrink:0}.editnames{margin-top:10px}details summary{cursor:pointer;font-weight:800}details>div{margin-top:11px}.stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.stat-box{border:1px solid var(--border);border-radius:11px;padding:12px;background:#101c16}.stat-box .big-figure{font-size:21px}.switch button{color:#fff}.switch button[aria-pressed=true]{border-color:var(--cream);background:#40583c}#switcher button{pointer-events:none;opacity:.8}.form-title{margin-bottom:12px}.round-pill{border:1px solid #607653;color:var(--lime);padding:4px 9px;border-radius:99px;font-size:12px;font-weight:700}.mono{font-variant-numeric:tabular-nums}#announcement{min-height:14px}@media(max-width:760px){.layout{grid-template-columns:1fr}.hero{grid-template-columns:1fr auto}.shell{padding:17px 12px 60px}.card{padding:15px}.player{padding:14px}.boss{grid-template-columns:1fr}.mark{width:46px;height:46px;font-size:28px}.stat-grid{grid-template-columns:1fr 1fr}}@media(max-width:400px){.cols3{grid-template-columns:1fr 1fr}.row.small-mobile{gap:5px}.button{padding:9px 10px}.player-title{font-size:14px}.score{font-size:32px}}\n</style>\n</head>\n<body>\n<main class=\"shell\">\n  <div class=\"topbar\"><span class=\"tiny\">THE STATIC COLLECTIVE / FIELD GAMES</span><button class=\"button small ghost\" id=\"shareTop\">◎ Cloud room</button></div>\n  <header class=\"hero\"><div><h1>THE PACT<span style=\"color:var(--lime)\">.</span></h1><p>A two-person life RPG. Friendly rivalry, mutual rescue, real-world results. No ads, account registration, or surprise obligations.</p></div><div class=\"mark\" aria-hidden=\"true\">✳</div></header>\n  <div class=\"status\"><span class=\"pill\" id=\"roundLabel\"></span><span class=\"pill\" id=\"cloudConnection\">Connecting to private cloud…</span><span class=\"pill\">Two independently authorized players</span></div>\n  <section class=\"score-grid\" aria-label=\"Players and scores\"><div class=\"card player\" id=\"youCard\"></div><div class=\"card player paula\" id=\"paulaCard\"></div></section>\n  <section class=\"card boss\" aria-label=\"Cooperative weekly goal\"><div><div class=\"tiny\">WEEKLY CO-OP BOSS</div><div class=\"boss-title\">Beat the week together</div><div class=\"small-note\" id=\"bossText\"></div><div class=\"bar\"><div class=\"fill\" id=\"bossFill\"></div></div></div><div class=\"big-figure mono\" id=\"bossScore\"></div></section>\n  <nav class=\"tabs\" role=\"tablist\"><button class=\"tab\" role=\"tab\" data-tab=\"quests\" aria-selected=\"true\">⚔ Quests</button><button class=\"tab\" role=\"tab\" data-tab=\"stakes\" aria-selected=\"false\">♜ Stakes</button><button class=\"tab\" role=\"tab\" data-tab=\"chronicle\" aria-selected=\"false\">☷ Chronicle</button><button class=\"tab\" role=\"tab\" data-tab=\"world\" aria-selected=\"false\">◇ World</button><button class=\"tab\" role=\"tab\" data-tab=\"witness\" aria-selected=\"false\">♫ WITNESS</button><button class=\"tab\" role=\"tab\" data-tab=\"sync\" aria-selected=\"false\">⇄ Exchange</button></nav>\n  <div class=\"layout\">\n    <div class=\"stack\">\n      <section id=\"questsTab\" class=\"stack\">\n        <section class=\"card\"><div class=\"section-head\"><h2>Quest board</h2><span class=\"round-pill\" id=\"questCount\"></span></div><div class=\"filterbar\" id=\"filters\"><button class=\"filter selected\" data-filter=\"all\">All</button><button class=\"filter\" data-filter=\"mine\">Mine</button><button class=\"filter\" data-filter=\"shared\">Co-op</button><button class=\"filter\" data-filter=\"pending\">Needs witness</button><button class=\"filter\" data-filter=\"done\">Completed</button></div><div id=\"quests\" class=\"stack\"></div></section>\n      </section>\n      <section id=\"stakesTab\" class=\"stack hidden\"><section class=\"card\"><h2>This week's wager</h2><p class=\"muted\">Agree on a friendly stake before the competition. Rewards are handled between you, never by this page.</p><div id=\"stakeDisplay\"></div></section><section class=\"card\"><h3>Propose a pact</h3><div class=\"stack\"><label class=\"field\">What are you playing for?<select id=\"stakeKind\"><option value=\"Meal\">A meal</option><option value=\"Favor\">A favor</option><option value=\"Money\">A small cash reward</option><option value=\"Custom\">Something custom</option></select></label><label class=\"field\">The agreed reward / forfeit<input id=\"stakeDetail\" maxlength=\"180\" placeholder=\"Loser makes the winner breakfast\"></label><label class=\"field\">Optional limit or rule<input id=\"stakeRule\" maxlength=\"180\" placeholder=\"Max $10; no pressure to participate\"></label><button class=\"button primary\" id=\"proposeStake\">Propose to the other player</button><p class=\"small-note\">Only the week’s higher *witnessed* XP determines the projected winner. No automatic debts, transfers, escrow, cannabis transactions, or payouts. Any custom reward must be lawful and consensual.</p></div></section></section>\n      <section id=\"chronicleTab\" class=\"stack hidden\"><section class=\"card\"><h2>Chronicle</h2><p class=\"muted\">A shared record of what actually happened, including proofs, encouragement, and agreements.</p><div id=\"feed\" class=\"feed\"></div></section></section>\n      <section id=\"witnessTab\" class=\"stack hidden\">\n<section class=\"card\"><div class=\"tiny\">WITNESS · COMMUNITY AUDIO BIBLE</div><h2>Freely offered readings</h2>\n<p class=\"muted\">People choose what to read. WITNESS remembers; listeners compose. Import a WITNESS audio Bible v1 backup package to verify the recording SHA-256 on this device. Linking a reading shares only its recording ID, passage, edition and digest—not the audio itself.</p>\n<label class=\"field\">WITNESS package (.json)<input id=\"witnessPackage\" type=\"file\" accept=\".json,application/json\"></label><div class=\"row\" style=\"margin:10px 0\"><button class=\"button small ghost\" id=\"clearWitness\">Clear loaded audio</button></div>\n<p class=\"small-note\" id=\"witnessImportStatus\" role=\"status\">No WITNESS recording package loaded.</p><div id=\"witnessImports\" class=\"stack\"></div>\n<p class=\"small-note\">Original <a href=\"https://github.com/the-static-collective/WITNESS/tree/genesis/community-audio-bible-001/prototype\" target=\"_blank\" rel=\"noreferrer\">WITNESS Matthew 5 recorder</a>. No verse assignments, quotas, public audio publication, or removal of previous takes.</p>\n</section>\n<section class=\"card\"><h2>Room recording references</h2><p class=\"small-note\">A reference is not voice authentication. A peer can report listening only after importing the matching audio into this page.</p><div id=\"witnessLinks\" class=\"stack\"></div></section>\n</section>\n<section id=\"worldTab\" class=\"stack hidden\"><section class=\"card\"><div class=\"tiny\">PACT × AUDIO WITNESS × FULL MEASURE</div><h2>World ledger</h2><p class=\"muted\">THE PACT awards friendly game XP. PACT peer receipts distinguish what was submitted, reviewed, accepted, or refused. WITNESS audio contributions remain a separate source. Full Measure alone decides whether a human-confirmed contribution becomes a Deed, Harvest, or Capacity. Nothing here grants those awards.</p><div id=\"worldStats\" class=\"row\" style=\"flex-wrap:wrap;gap:8px\"></div><p class=\"small-note\">Impact claims and their peer reviews are local evidence candidates, not independent beneficiary confirmation or Full Measure admission.</p></section><div id=\"worldEntries\" class=\"stack\"></div></section>\n       <section id=\"syncTab\" class=\"stack hidden\"><section class=\"card\"><h2>Private cloud room</h2><p class=\"muted\">Both phones read the same server ledger. Each player has a separate secret link. Changes refresh automatically every 15 seconds while the page is open.</p><div class=\"stack\"><div class=\"row\"><button class=\"button primary\" id=\"copyMyLink\">Copy my private link</button><button class=\"button\" id=\"refreshNow\">Refresh now</button></div><p class=\"small-note\" id=\"roomStatus\">Connecting…</p><div class=\"hint\">Do not send your own private link to the other player. Each link controls one person’s seat. Paula should receive her own private invitation link from the organizer.</div><label class=\"field\">Room ID<input id=\"roomIdField\" readonly></label></div><div class=\"hidden\"><input id=\"nameYou\"><input id=\"namePaula\"></div></section></section>\n    </div>\n    <aside class=\"stack\"><section class=\"card\"><div class=\"tiny\">WHO'S AT THE CONTROLS?</div><h3 style=\"margin-top:6px\">Playing as</h3><div class=\"row switch\" id=\"switcher\"></div><p class=\"small-note\" style=\"margin-bottom:0;margin-top:10px\">Your private link controls your identity. You cannot approve your own tasks.</p></section>\n    <section class=\"card\"><h2 class=\"form-title\">New quest <span style=\"color:var(--lime)\">+</span></h2><form id=\"questForm\" class=\"stack\"><label class=\"field\">What needs doing?<input id=\"questTitle\" required maxlength=\"140\" placeholder=\"Bake cookies for FELLOWSHIP\"></label><div class=\"cols2\"><label class=\"field\">Assigned to<select id=\"questOwner\"><option value=\"you\">You</option><option value=\"paula\">Paula</option><option value=\"both\">Both (co-op)</option></select></label><label class=\"field\">Reward<select id=\"questXP\"><option value=\"10\">10 XP · Small</option><option value=\"25\" selected>25 XP · Medium</option><option value=\"50\">50 XP · Boss</option></select></label></div><div class=\"cols2\"><label class=\"field\">Field<select id=\"questCategory\"><option>FELLOWSHIP</option><option>HUMKIN</option><option>LIFE</option><option>OTHER</option></select></label><label class=\"field\">Due date (optional)<input type=\"date\" id=\"questDue\"></label></div><label class=\"field\">Notes (optional)<textarea id=\"questNotes\" rows=\"2\" maxlength=\"500\" placeholder=\"What would count as finished?\"></textarea></label><button type=\"submit\" class=\"button primary\">Add quest</button></form></section>\n    <section class=\"card\"><div class=\"tiny\">FRIENDSHIP > LEADERBOARD</div><h3 style=\"margin-top:8px\">Send encouragement</h3><label class=\"field\">One good word<input id=\"cheerText\" maxlength=\"180\" placeholder=\"You got this. I can help.\"></label><div class=\"row\" style=\"margin-top:10px\"><button class=\"button\" id=\"cheerButton\">Send a cheer</button><button class=\"button ghost\" id=\"graceButton\">Use grace day</button></div><p class=\"small-note\" id=\"graceStatus\" style=\"margin:10px 0 0\"></p></section>\n    </aside>\n  </div>\n  <footer class=\"footer small-note\">THE PACT v0.4 · AUDIO WITNESS × FULL MEASURE • Private bearer-link access; treat your link like a password. No payments, escrow, or outside proof verification.</footer>\n</main>\n<div class=\"toast hidden\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n<div class=\"hidden\" id=\"announcement\" aria-live=\"polite\"></div>\n<script>\n'use strict';\nconst KEY='the-pact-prototype-v01';let witnessLoaded=[],witnessUrls=[];\nconst $=id=>document.getElementById(id);\nconst uuid=()=>typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():('id-'+Date.now()+'-'+Math.random().toString(36).slice(2));\nconst iso=()=>new Date().toISOString();\nconst today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};\nconst localDate=x=>{const d=new Date(x);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};\nconst dayShift=(str,delta)=>{const d=new Date(str+'T12:00:00');d.setDate(d.getDate()+delta);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};\nconst weekOf=(d=today())=>{const a=new Date(d+'T12:00:00');const mon=(a.getDay()+6)%7;return dayShift(d,-mon)};\nconst endOfWeek=(w=weekOf())=>dayShift(w,6);\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst fmtTime=s=>new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});\nconst storage=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}};\nconst empty=()=>({version:1,roomId:uuid(),createdAt:iso(),names:{you:'You',paula:'Paula'},events:[]});\nlet db=empty();\nif(!db||db.version!==1||!Array.isArray(db.events)||!db.roomId)db=empty();\nlet actor='you', tab='quests',filter='all';\nconst persist=()=>{};\npersist();\nconst name=p=>db.names[p]||p;\nconst other=p=>p==='you'?'paula':'you';\nconst addEvent=async(type,data={})=>{try{await cloudCall({op:'event',type,data,id:uuid()});await refreshGame();notify('Saved to the shared room.');return true}catch(err){notify('NOT saved: '+err.message);return false}};\nconst fold=()=>{\n const state={quests:{},stake:{},graces:{},cheers:[],help:[],impacts:{},witnesses:{}};\n for(const e of [...db.events].sort((a,b)=>(a.seq||0)-(b.seq||0)||String(a.at).localeCompare(String(b.at)))){\n  const d=e.data||{};\n  if(e.type==='quest.create')state.quests[d.id]={...d,status:'open',createdAt:e.at,creator:e.actor};\n  if(e.type==='quest.edit'&&state.quests[d.id]&&['open','needs_revision'].includes(state.quests[d.id].status))Object.assign(state.quests[d.id],d.changes);\n  if(e.type==='quest.remove'&&state.quests[d.id]&&['open','needs_revision'].includes(state.quests[d.id].status))state.quests[d.id].removed=true;\n  if(e.type==='quest.submit'&&state.quests[d.id]&&['open','needs_revision'].includes(state.quests[d.id].status)){\n    const q=state.quests[d.id];if(q.owner===e.actor||q.owner==='both')Object.assign(q,{status:'pending',proof:d.proof||'',subjectDigest:d.subjectDigest||'',submittedBy:e.actor,submittedAt:e.at,refusalReason:''});\n  }\n  if(e.type==='quest.verify'&&state.quests[d.id]&&state.quests[d.id].status==='pending'){\n    const q=state.quests[d.id];if(q.submittedBy!==e.actor)Object.assign(q,{status:'done',verifiedBy:e.actor,verifiedAt:e.at,witnessMode:d.mode||'legacy',witnessNote:d.note||''});\n  }\n  if(e.type==='quest.refuse'&&state.quests[d.id]?.status==='pending'){const q=state.quests[d.id];Object.assign(q,{status:'needs_revision',refusalReason:d.reason||'',refusedBy:e.actor,refusedAt:e.at});}\n  if(e.type==='witness.link')state.witnesses[d.id]={...d,linkedBy:e.actor,linkedAt:e.at,withdrawn:false,reviews:[]};\n  if(e.type==='witness.review'&&state.witnesses[d.id]&&!state.witnesses[d.id].withdrawn)state.witnesses[d.id].reviews.push({actor:e.actor,mode:d.mode,note:d.note||'',at:e.at});\n  if(e.type==='witness.withdraw'&&state.witnesses[d.id])state.witnesses[d.id].withdrawn=true;\n  if(e.type==='impact.report'&&state.quests[d.id]?.status==='done')state.impacts[d.id]={...d,reporter:e.actor,reportedAt:e.at,reportEventId:e.id,review:null};\n  if(e.type==='impact.review'&&state.impacts[d.id])state.impacts[d.id].review={mode:d.mode,note:d.note||'',reviewer:e.actor,reviewedAt:e.at,eventId:e.id};\n  if(e.type==='quest.reopen'&&state.quests[d.id]){delete state.impacts[d.id];Object.assign(state.quests[d.id],{status:'open',submittedBy:null,submittedAt:null,verifiedBy:null,verifiedAt:null,proof:'',subjectDigest:'',witnessMode:'',witnessNote:''});}\n  if(e.type==='stake.propose')state.stake[e.week]={id:d.id,kind:d.kind,detail:d.detail,rule:d.rule,accepted:{[e.actor]:true},proposer:e.actor,at:e.at};\n  if(e.type==='stake.accept'&&state.stake[e.week]?.id===d.id)state.stake[e.week].accepted[e.actor]=true;\n  if(e.type==='grace.use')state.graces[e.week+':'+e.actor]={day:localDate(e.at),at:e.at};\n  if(e.type==='cheer.add')state.cheers.push(e);\n  if(e.type==='help.offer')state.help.push(e);\n }\n return state;\n};\nconst isWeekDone=q=>q.status==='done'&&weekOf(localDate(q.verifiedAt))===weekOf();\nconst scores=state=>{const out={you:0,paula:0};for(const q of Object.values(state.quests)){if(q.removed||!isWeekDone(q))continue;if(q.owner==='both'){out.you+=q.xp;out.paula+=q.xp;}else out[q.owner]+=q.xp;}return out;};\nconst streak=(state,p)=>{const days=new Set();for(const q of Object.values(state.quests)){if(q.removed||q.status!=='done')continue;if(q.owner===p||q.owner==='both')days.add(localDate(q.verifiedAt));}for(const [k,v] of Object.entries(state.graces))if(k.endsWith(':'+p))days.add(v.day);let d=today(),s=0;if(!days.has(d))d=dayShift(d,-1);for(let i=0;i<90&&days.has(d);i++){s++;d=dayShift(d,-1);}return s;};\nfunction notify(msg){const t=$('toast');t.textContent=msg;t.classList.remove('hidden');setTimeout(()=>{if(t.textContent===msg)t.classList.add('hidden')},3200)}\nfunction renderPlayers(state,score){for(const p of ['you','paula']){const card=$(p+'Card');card.classList.toggle('active',actor===p);card.innerHTML=`<div class=\"row between\"><div class=\"player-title\"><span class=\"avatar\">${p==='you'?'✳':'✦'}</span><strong>${esc(name(p))}</strong></div><button class=\"button small ${actor===p?'primary':'ghost'}\" data-switch=\"${p}\">${actor===p?'Playing':'Play as'}</button></div><div class=\"score mono\">${score[p]} <span>XP</span></div><div class=\"bar\"><div class=\"fill\" style=\"width:${Math.min(score[p]/125*100,100)}%\"></div></div><div class=\"row between\"><span class=\"subtle\">${streak(state,p)}-day momentum</span><span class=\"subtle\">${score[p]>=125?'LEVEL UP':'Next level: '+Math.max(0,125-score[p])+' XP'}</span></div>`}}\nfunction renderQuests(state){const quests=Object.values(state.quests).filter(q=>!q.removed).sort((a,b)=>{const v={pending:0,open:1,done:2};return v[a.status]-v[b.status]||String(a.due||'9999').localeCompare(String(b.due||'9999'))||a.createdAt.localeCompare(b.createdAt)});\n $('questCount').textContent=quests.filter(x=>x.status==='open').length+' open';\n const shown=quests.filter(q=>filter==='all'||filter==='mine'&&(q.owner===actor||q.owner==='both')||filter==='shared'&&q.owner==='both'||filter==='pending'&&q.status==='pending'||filter==='done'&&q.status==='done');\n $('quests').innerHTML=shown.length?shown.map(q=>{const own=q.owner==='both'?'Co-op':name(q.owner),isLate=q.due&&q.due<today()&&q.status!=='done';const status=q.status==='open'?'OPEN':q.status==='pending'?'AWAITING WITNESS':q.status==='needs_revision'?'NEEDS MORE EVIDENCE':'PEER CONFIRMED';const canSubmit=(q.status==='open'||q.status==='needs_revision')&&(q.owner===actor||q.owner==='both');const canVerify=q.status==='pending'&&q.submittedBy!==actor;const offered=state.help.some(e=>e.data.id===q.id&&e.actor===actor);\n  return `<article class=\"card quest\"><div class=\"quest-head\"><div><div class=\"tags\"><span class=\"tag\">${esc(q.category)}</span><span class=\"tag ${q.owner==='both'?'blue':''}\">${esc(own)}</span><span class=\"tag gold\">+${q.xp} XP${q.owner==='both'?' EACH':''}</span></div><div class=\"quest-title\">${esc(q.title)}</div></div><span class=\"tag ${q.status==='pending'?'rose':q.status==='done'?'blue':''}\">${status}</span></div>${q.due?`<p class=\"small-note\" style=\"color:${isLate?'var(--rose)':'var(--muted)'}\">Due ${esc(q.due)}${isLate?' · past due':''}</p>`:''}${q.notes?`<p class=\"small-note\">${esc(q.notes)}</p>`:''}${q.proof?`<p class=\"hint\">Evidence: ${esc(q.proof)}</p>`:''}${q.status==='pending'?`<p class=\"small-note\">Submitted by ${esc(name(q.submittedBy))}. Other player: report precisely what you can attest.</p>`:''}${q.status==='done'?`<p class=\"small-note\">Peer confirmation ${fmtTime(q.verifiedAt)} by ${esc(name(q.verifiedBy))} · ${esc(q.witnessMode||'unspecified basis')}${q.witnessNote?' · '+esc(q.witnessNote):''}</p>`:''}${q.status==='needs_revision'?`<p class=\"hint\">Witness refused: ${esc(q.refusalReason||'More evidence requested')}</p>`:''}${q.subjectDigest?`<p class=\"small-note mono\" style=\"overflow-wrap:anywhere\">Presented subject SHA-256: ${esc(q.subjectDigest.slice(0,20))}…</p>`:''}<div class=\"quest-actions\">${canSubmit?`<button class=\"button small primary\" data-action=\"submit\" data-id=\"${esc(q.id)}\">Submit completion</button>`:''}${canVerify?`<button class=\"button small primary\" data-action=\"verify\" data-id=\"${esc(q.id)}\" >Review & confirm</button><button class=\"button small ghost warn\" data-action=\"refuse\" data-id=\"${esc(q.id)}\">Refuse / ask more</button>`:''}${q.status!=='done'&&q.owner!=='both'&&q.owner!==actor?`<button class=\"button small ghost\" data-action=\"help\" data-id=\"${esc(q.id)}\" ${offered?'disabled':''}>${offered?'Help offered':'Offer help'}</button>`:''}${(q.status==='open'||q.status==='needs_revision')?`<button class=\"button small ghost\" data-action=\"edit\" data-id=\"${esc(q.id)}\">Edit</button><button class=\"button small ghost warn\" data-action=\"remove\" data-id=\"${esc(q.id)}\">Remove</button>`:''}${q.status!=='open'?`<button class=\"button small ghost\" data-action=\"reopen\" data-id=\"${esc(q.id)}\">Reopen</button>`:''}</div></article>`;\n }).join(''):'<div class=\"empty\"><strong>No quests in this view.</strong>Add a task on the right, or switch to All.</div>';\n for(const b of document.querySelectorAll('[data-filter]'))b.classList.toggle('selected',b.dataset.filter===filter);\n}\nfunction renderStake(state,score){const w=weekOf();const st=state.stake[w];const s=$('stakeDisplay');$('proposeStake').disabled=false;const projected=score.you===score.paula?'Currently tied':(score.you>score.paula?name('you'):name('paula'))+' is ahead';\n if(!st){s.innerHTML='<div class=\"stake-hero\"><div class=\"tiny\">NO AGREEMENT YET</div><h3 style=\"margin-top:9px\">The stakes are yours to choose.</h3><p style=\"margin:0;color:var(--muted)\">Try a breakfast, a chore, or a capped token amount. Both people must agree.</p></div>';return;}\n const both=st.accepted.you&&st.accepted.paula;\n s.innerHTML=`<div class=\"stake-hero\"><div class=\"tiny\">${both?'PACT ACTIVE':'PROPOSAL · AWAITING SIGNATURE'}</div><div class=\"big-figure\" style=\"font-size:26px;margin-top:9px\">${esc(st.detail)}</div><p class=\"small-note\">Type: ${esc(st.kind)}${st.rule?' · Rule: '+esc(st.rule):''}</p><div class=\"row\" style=\"margin:15px 0\"><span class=\"stamp ${st.accepted.you?'ok':''}\">${esc(name('you'))}: ${st.accepted.you?'agreed':'pending'}</span><span class=\"stamp ${st.accepted.paula?'ok':''}\">${esc(name('paula'))}: ${st.accepted.paula?'agreed':'pending'}</span></div><div class=\"hint\">${both?esc(projected)+'. Round runs through '+endOfWeek(w)+'. Confirm any actual reward privately after it ends.':'The next player must accept before this pact becomes active.'}</div>${!st.accepted[actor]?`<button class=\"button primary\" id=\"acceptStake\" style=\"margin-top:14px\">${esc(name(actor))}: I agree</button>`:''}</div>`;\n $('proposeStake').disabled=!!both;\n if(both)$('proposeStake').title='This week already has an active pact';else $('proposeStake').title='';\n}\nfunction describe(e,state){const d=e.data||{},n=esc(name(e.actor));const q=state.quests[d.id];const title=q?esc(q.title):'a quest';switch(e.type){case 'quest.create':return `<strong>${n}</strong> added a quest: ${esc(d.title)}`;case 'quest.edit':return `<strong>${n}</strong> edited ${title}`;case 'quest.remove':return `<strong>${n}</strong> removed ${title}`;case 'quest.submit':return `<strong>${n}</strong> submitted completion of ${title}`;case 'quest.verify':return `<strong>${n}</strong> recorded peer confirmation of ${title} (${esc(d.mode||'legacy')})`;case 'quest.refuse':return `<strong>${n}</strong> refused the current proof on ${title}: ${esc(d.reason||'more detail needed')}`;case 'impact.report':return `<strong>${n}</strong> proposed a world-effect claim for ${title}`;case 'impact.review':return `<strong>${n}</strong> ${d.mode==='questioned'?'questioned':'reviewed'} the world-effect claim for ${title}`;case 'witness.link':return `<strong>${n}</strong> linked a WITNESS reading at ${esc(d.passage)}`;case 'witness.review':return `<strong>${n}</strong> ${d.mode==='heard'?'reported listening to':'acknowledged metadata for'} a WITNESS recording`;case 'witness.withdraw':return `<strong>${n}</strong> withdrew a WITNESS recording link`;case 'quest.reopen':return `<strong>${n}</strong> reopened ${title}`;case 'stake.propose':return `<strong>${n}</strong> proposed a stake: ${esc(d.detail)}`;case 'stake.accept':return `<strong>${n}</strong> accepted this week's pact`;case 'grace.use':return `<strong>${n}</strong> used a grace day`;case 'cheer.add':return `<strong>${n}</strong> encouraged ${esc(name(other(e.actor)))}: “${esc(d.text)}”`;case 'help.offer':return `<strong>${n}</strong> offered help on ${title}`;default:return `<strong>${n}</strong> updated the game`}}\nfunction renderFeed(state){$('feed').innerHTML=db.events.length?[...db.events].sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,75).map(e=>`<div class=\"feed-item\"><div>${describe(e,state)}</div><div class=\"feed-time\">${fmtTime(e.at)}</div></div>`).join(''):'<div class=\"empty\">Your story starts with the first quest.</div>'}\n\n\nfunction renderWitness(s){\n const all=Object.values(s.witnesses).sort((a,b)=>String(b.linkedAt).localeCompare(String(a.linkedAt)));\n $('witnessLinks').innerHTML=all.length?all.map(w=>{\n const peer=w.reviews.find(x=>x.actor!==w.linkedBy);\n const localCopy=witnessLoaded.some(x=>x.recordingId===w.recordingId&&x.hash===w.hash);\n const description=peer?(peer.mode==='heard'?'Listening reported by ':'Reference acknowledged by ')+name(peer.actor):'Not yet reviewed by partner';\n return '<div class=\"hint\"><strong>'+esc(w.passage)+'</strong> · '+esc(w.edition)+\n '<p class=\"small-note mono\" style=\"overflow-wrap:anywhere\">Recording '+esc(w.recordingId)+' · '+esc(w.hash.slice(0,24))+'…</p>'+\n '<p class=\"small-note\">'+esc(description)+(w.withdrawn?' · Reference withdrawn':'')+'</p>'+\n '<div class=\"quest-actions\">'+(!w.withdrawn&&!peer&&w.linkedBy!==actor?'<button class=\"button small ghost\" data-wreview=\"metadata\" data-id=\"'+esc(w.id)+'\">Acknowledge metadata</button>':'')+\n (!w.withdrawn&&!peer&&w.linkedBy!==actor&&localCopy?'<button class=\"button small primary\" data-wreview=\"heard\" data-id=\"'+esc(w.id)+'\">I listened to this take</button>':'')+\n (!w.withdrawn&&w.linkedBy===actor?'<button class=\"button small ghost warn\" data-wwithdraw=\"'+esc(w.id)+'\">Withdraw reference</button>':'')+\n '<button class=\"button small ghost\" data-wpacket=\"'+esc(w.id)+'\">Copy Full Measure candidate</button></div></div>';\n }).join(''):'<div class=\"empty\">No WITNESS recordings linked yet. Import a WITNESS package above to start.</div>';\n const active=all.filter(w=>!w.withdrawn);\n $('worldStats').insertAdjacentHTML('beforeend','<span class=\"pill\">'+active.length+' audio references</span><span class=\"pill\">'+active.filter(w=>w.reviews.some(x=>x.mode==='heard')).length+' peer listening reports</span>');\n}\nfunction clearWitnessAudio(){\n witnessUrls.forEach(url=>URL.revokeObjectURL(url));\n witnessUrls=[];witnessLoaded=[];\n $('witnessPackage').value='';\n $('witnessImports').innerHTML='';\n}\nasync function loadWitnessPackage(file){\n if(!file)return;\n if(file.size>28*1024*1024)throw Error('Package too large; max 28 MB');\n const pkg=JSON.parse(await file.text());\n if(pkg.witness_format!=='witness-package'||pkg.version!==1)throw Error('Expected a WITNESS v1 package');\n if(typeof pkg.chapter?.id!=='string'||typeof pkg.chapter?.text_edition?.id!=='string')throw Error('Passage or edition missing');\n if(!Array.isArray(pkg.recordings)||!pkg.recordings.length||pkg.recordings.length>100)throw Error('Package must contain 1–100 recordings');\n const incoming=[],urls=[];let total=0;\n try{\n  for(const rec of pkg.recordings){\n   if(typeof rec.audio_base64!=='string'||!/^[a-f0-9]{64}$/i.test(rec.sha256||''))throw Error('Missing audio digest');\n   if(rec.audio_base64.length>12_000_000||!/^[A-Za-z0-9+/=\\s]+$/.test(rec.audio_base64))throw Error('Invalid audio base64');\n   total+=rec.audio_base64.length;if(total>26*1024*1024)throw Error('Package audio exceeds import budget');\n   const raw=atob(rec.audio_base64.replace(/\\s+/g,''));\n   const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));\n   const digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join('');\n   if(digest!==rec.sha256.toLowerCase())throw Error('Checksum mismatch for recording '+String(rec.recording_id||'').slice(0,40));\n   const mime=['audio/webm','audio/ogg','audio/mp4','audio/mpeg','audio/x-m4a'].find(v=>(rec.media_type||'').startsWith(v))||'audio/webm';\n   const url=URL.createObjectURL(new Blob([bytes],{type:mime}));urls.push(url);\n   incoming.push({url,recordingId:String(rec.recording_id||''),hash:digest,passage:String(rec.passage_start||pkg.chapter.id)+'.'+Number(rec.verse),edition:String(rec.text_edition_id||pkg.chapter.text_edition.id),recordedAt:String(rec.recorded_at||''),license:String(rec.recording_license||''),source:'witness-package-v1'});\n  }\n }catch(error){urls.forEach(url=>URL.revokeObjectURL(url));throw error}\n clearWitnessAudio();\n witnessLoaded=incoming;witnessUrls=urls;\n $('witnessImportStatus').textContent=incoming.length+' audio SHA-256 checksum(s) verified locally. Audio has NOT left this phone.';\n $('witnessImports').innerHTML=incoming.map((item,i)=>'<div class=\"hint\"><strong>'+esc(item.passage)+'</strong> · '+esc(item.edition)+'<audio controls preload=\"none\" src=\"'+esc(item.url)+'\" style=\"width:100%;margin-top:6px\"></audio><div class=\"quest-actions\"><button class=\"button small primary\" data-wlink=\"'+i+'\">Link this reading (metadata only)</button></div></div>').join('');\n render();\n}\n$('witnessPackage').addEventListener('change',async event=>{\n try{await loadWitnessPackage(event.target.files?.[0])}catch(error){clearWitnessAudio();$('witnessImportStatus').textContent='Import refused: '+error.message;notify('Recording package was not accepted')}\n});\n$('clearWitness').addEventListener('click',()=>{clearWitnessAudio();$('witnessImportStatus').textContent='Loaded audio cleared from this tab; WITNESS files and archives unchanged.';render();});\ndocument.addEventListener('click',async event=>{\n const link=event.target.closest('[data-wlink]');\n if(link){\n  const rec=witnessLoaded[Number(link.dataset.wlink)];if(!rec)return;\n  if(!confirm('Share this recording citation and SHA-256 with your private PACT room? No audio upload, no public release.'))return;\n  await addEvent('witness.link',{id:uuid(),recordingId:rec.recordingId,hash:rec.hash,passage:rec.passage,edition:rec.edition,recordedAt:rec.recordedAt,license:rec.license,source:rec.source});\n  return;\n }\n const review=event.target.closest('[data-wreview]');\n if(review){\n  const w=fold().witnesses[review.dataset.id];if(!w||w.withdrawn||w.linkedBy===actor)return;\n  const mode=review.dataset.wreview;\n  if(mode==='heard'&&!witnessLoaded.some(x=>x.recordingId===w.recordingId&&x.hash===w.hash)){notify('Import and play the matching audio first.');return}\n  const note=prompt(mode==='heard'?'You attest that you listened to this audio take. A listening report does not verify speaker identity or textual accuracy. Note (optional):':'You are acknowledging metadata only, not that you heard this audio. Note (optional):','');\n  if(note===null)return;await addEvent('witness.review',{id:w.id,mode,note:note.slice(0,240)});return;\n }\n const withdraw=event.target.closest('[data-wwithdraw]');\n if(withdraw){if(confirm('Withdraw this PACT reference? Original WITNESS recording stays untouched; history records the withdrawal.'))await addEvent('witness.withdraw',{id:withdraw.dataset.wwithdraw});return;}\n const packet=event.target.closest('[data-wpacket]');\n if(packet){\n  const w=fold().witnesses[packet.dataset.wpacket];if(!w)return;\n  const candidate={schema:'static-collective.witness-pact-full-measure-candidate.v1',source:{project:'WITNESS community audio Bible',bridge:'THE PACT v0.4',room:db.roomId},recording:{recordingId:w.recordingId,sha256:w.hash,passage:w.passage,edition:w.edition,recordedAt:w.recordedAt,declaredLicense:w.license},bridge:{linkedBy:w.linkedBy,linkedAt:w.linkedAt,withdrawn:w.withdrawn,peerReports:w.reviews},events:db.events.filter(e=>e.data?.id===w.id).map(e=>({seq:e.seq,id:e.id,actor:e.actor,type:e.type,at:e.at,data:e.data})),awards:{Deeds:0,Harvests:0,Capacity:0},status:'REVIEW_ONLY',boundary:'No audio embedded. Digest check was performed on the importers device. No authenticated identity, Scripture fidelity, beneficiary confirmation, or Full Measure award is implied.'};\n  const raw=JSON.stringify(candidate,null,2);navigator.clipboard.writeText(raw).then(()=>notify('WITNESS candidate metadata copied.')).catch(()=>prompt('Copy review packet:',raw));\n }\n});\n\nfunction renderWorld(s){\n const done=Object.values(s.quests).filter(q=>!q.removed&&q.status==='done');\n const reported=done.filter(q=>s.impacts[q.id]);\n const reviewed=reported.filter(q=>s.impacts[q.id].review?.mode==='reviewed');\n $('worldStats').innerHTML='<span class=\"pill\">'+done.length+' peer-confirmed quests</span><span class=\"pill\">'+reported.length+' consequence candidates</span><span class=\"pill\">'+reviewed.length+' peer-reviewed claims</span><span class=\"pill\">0 Full Measure Deeds awarded here</span>';\n $('worldEntries').innerHTML=done.length?done.map(q=>{\n const v=s.impacts[q.id],own=q.submittedBy===actor,mayReport=own&&!v,mayReview=!own&&v&&!v.review;\n return '<article class=\"card\"><div class=\"tiny\">QUEST / '+esc(q.category)+'</div><h3 style=\"margin:6px 0\">'+esc(q.title)+'</h3><p class=\"small-note\">Submission by '+esc(name(q.submittedBy))+' • review basis: '+esc(q.witnessMode||'unspecified')+' • presented digest: '+esc((q.subjectDigest||'unbound').slice(0,18))+'…</p>'+\n (v?'<div class=\"hint\"><strong>Consequence candidate</strong><div>Before: '+esc(v.before||'not stated')+'</div><div>After: '+esc(v.after)+'</div><div>Beneficiary: '+esc(v.beneficiary||'not stated')+'</div><div>Peer review: '+esc(v.review?v.review.mode+' ('+name(v.review.reviewer)+')':'awaiting review')+'</div></div>':'<p class=\"small-note\">No measurable consequence reported yet. XP does not imply a Deed.</p>')+\n '<div class=\"quest-actions\">'+(mayReport?'<button class=\"button small primary\" data-action=\"report-impact\" data-id=\"'+esc(q.id)+'\">Record an outcome claim</button>':'')+\n (mayReview?'<button class=\"button small\" data-action=\"review-impact\" data-id=\"'+esc(q.id)+'\">Review outcome</button>':'')+\n '<button class=\"button small ghost\" data-action=\"copy-packet\" data-id=\"'+esc(q.id)+'\">Copy Full Measure review packet</button></div></article>';\n }).join(''):'<div class=\"card\"><p class=\"muted\">Once a quest receives peer confirmation, its human encounter and possible consequence appear here.</p></div>';\n}\n\nfunction render(){const s=fold(),sc=scores(s),total=sc.you+sc.paula;const w=weekOf();\n $('roundLabel').textContent='Round · '+w+' → '+endOfWeek(w);\n renderPlayers(s,sc);$('bossText').textContent=total>=200?'BOSS DEFEATED. Keep going together.':`${Math.max(0,200-total)} XP until the shared 200 XP goal`;\n $('bossFill').style.width=Math.min(total/200*100,100)+'%';$('bossScore').textContent=total+' / 200';\n $('switcher').innerHTML=['you','paula'].map(p=>`<button class=\"button small\" data-switch=\"${p}\" aria-pressed=\"${actor===p}\">${esc(name(p))}</button>`).join('');\n $('graceStatus').textContent=s.graces[w+':'+actor]?'Grace used this week · your momentum is protected today':'1 grace day available this week';$('graceButton').disabled=!!s.graces[w+':'+actor];\n $('questOwner').querySelector('[value=\"you\"]').textContent=name('you');$('questOwner').querySelector('[value=\"paula\"]').textContent=name('paula');\n renderQuests(s);renderStake(s,sc);renderFeed(s);renderWorld(s);renderWitness(s);$('roomIdField').value=db.roomId;$('nameYou').value=name('you');$('namePaula').value=name('paula');\n for(const nameTab of ['quests','stakes','chronicle','world','witness','sync'])$(nameTab+'Tab').classList.toggle('hidden',tab!==nameTab);\n for(const b of document.querySelectorAll('[data-tab]'))b.setAttribute('aria-selected',String(b.dataset.tab===tab));\n}\ndocument.addEventListener('click',e=>{\n const switchButton=e.target.closest('[data-switch]');if(switchButton){notify('Each player must use their own private access link.');return}\n const tabButton=e.target.closest('[data-tab]');if(tabButton){tab=tabButton.dataset.tab;render();return}\n const filterButton=e.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;render();return}\n const a=e.target.closest('[data-action]');if(!a)return;\n const q=fold().quests[a.dataset.id];if(!q)return;const action=a.dataset.action;\n if(action==='submit'){const proof=prompt('What was completed? Add a short proof note (optional).','');if(proof===null)return;addEvent('quest.submit',{id:q.id,proof:proof.slice(0,500)});notify('Submitted to '+name(other(actor))+' for witnessing.')}\n if(action==='verify'){if(!q.subjectDigest){notify('This submission lacks a bound subject. Request a fresh submission.');return;}const mode=prompt('What can you ACTUALLY attest? Type observed, reviewed, or trusted.\\n observed = personally saw the work\\n reviewed = examined evidence\\n trusted = accept the person\\n None of these grants a Full Measure Deed.', 'reviewed');if(mode===null)return;const norm=mode.trim().toLowerCase();if(!['observed','reviewed','trusted'].includes(norm)){notify('Use observed, reviewed, or trusted.');return;}const note=prompt('Briefly describe what you actually saw or reviewed (optional).','');if(note===null)return;addEvent('quest.verify',{id:q.id,subjectDigest:q.subjectDigest,mode:norm,note:note.slice(0,240)});}\n  if(action==='refuse'){const reason=prompt('What cannot you confirm? This refusal is preserved without erasing the submission.','Need clearer evidence');if(reason===null)return;addEvent('quest.refuse',{id:q.id,subjectDigest:q.subjectDigest,reason:reason.slice(0,240)});}\n  if(action==='report-impact'){const before=prompt('Before: what was the situation? (optional)','');if(before===null)return;const after=prompt('After: what changed in the real world?','');if(after===null||!after.trim())return;const beneficiary=prompt('Who benefits? (plain language, no private identifying details)','');if(beneficiary===null)return;addEvent('impact.report',{id:q.id,before:before.slice(0,240),after:after.slice(0,240),beneficiary:beneficiary.slice(0,120)});}\n  if(action==='review-impact'){const mode=prompt('Peer review: type reviewed or questioned. This is not recipient confirmation.','reviewed');if(mode===null)return;const norm=mode.trim().toLowerCase();if(!['reviewed','questioned'].includes(norm)){notify('Use reviewed or questioned.');return;}const note=prompt('What do you know or still need?','');if(note===null)return;addEvent('impact.review',{id:q.id,mode:norm,note:note.slice(0,240)});}\n  if(action==='copy-packet'){const s=fold(),impact=s.impacts[q.id]||null;const events=db.events.filter(e=>e.data?.id===q.id).map(e=>({eventId:e.id,sequence:e.seq||null,type:e.type,actor:e.actor,at:e.at,data:e.data}));const packet={schema:'static-collective.pact-world-review.v1',source:{project:'THE PACT / planZ',room:db.roomId,readAt:new Date().toISOString()},subject:{questId:q.id,title:q.title,owner:q.owner,notes:q.notes||'',reportedBy:q.submittedBy,proof:q.proof||'',sha256:q.subjectDigest||''},humanEncounter:{peer:q.verifiedBy||null,basis:q.witnessMode||null,note:q.witnessNote||null,at:q.verifiedAt||null},candidateImpact:impact,events,claimState:'UNVERIFIED_FULL_MEASURE_CANDIDATE',awards:{Deeds:0,Harvests:0,Capacity:0},boundary:'Peer-confirmed game XP does not grant Deed or authority. PACT is not an independent recipient or a Full Measure authority.'};const out=JSON.stringify(packet,null,2);navigator.clipboard.writeText(out).then(()=>notify('Review packet copied; share only with an intended reviewer.')).catch(()=>prompt('Copy review packet:',out));}\n\n if(action==='reopen'){if(!confirm('Reopen this quest? It will no longer count toward verified XP.'))return;addEvent('quest.reopen',{id:q.id});notify('Quest reopened.')}\n if(action==='remove'){if(!confirm('Remove this unfinished quest from the board?'))return;addEvent('quest.remove',{id:q.id});notify('Quest removed.')}\n if(action==='help'){addEvent('help.offer',{id:q.id});notify('Offer of help recorded.')}\n if(action==='edit'){const title=prompt('Quest title',q.title);if(title===null||!title.trim())return;const note=prompt('Notes / definition of done',q.notes||'');if(note===null)return;addEvent('quest.edit',{id:q.id,changes:{title:title.trim().slice(0,140),notes:note.slice(0,500)}});notify('Quest updated.')}\n});\n$('questForm').addEventListener('submit',e=>{e.preventDefault();const title=$('questTitle').value.trim();if(!title)return;addEvent('quest.create',{id:uuid(),title,owner:$('questOwner').value,xp:Number($('questXP').value),category:$('questCategory').value,due:$('questDue').value,notes:$('questNotes').value.trim()}).then(ok=>{if(ok){$('questForm').reset();$('questXP').value='25';$('questCategory').value='FELLOWSHIP';}})});\n$('proposeStake').addEventListener('click',()=>{const detail=$('stakeDetail').value.trim(),kind=$('stakeKind').value,rule=$('stakeRule').value.trim();if(!detail){notify('Describe the reward first.');$('stakeDetail').focus();return}const s=fold();const old=s.stake[weekOf()];if(old?.accepted.you&&old?.accepted.paula){notify('The active pact is locked for this week.');return}if(old&&!confirm('Replace the existing unsigned proposal?'))return;addEvent('stake.propose',{id:uuid(),kind,detail,rule}).then(ok=>{if(ok){$('stakeDetail').value='';$('stakeRule').value='';}});});\ndocument.addEventListener('click',e=>{if(e.target.id==='acceptStake'){const st=fold().stake[weekOf()];if(!st||st.accepted[actor])return;addEvent('stake.accept',{id:st.id});notify('Pact accepted!')}});\n$('cheerButton').addEventListener('click',()=>{let t=$('cheerText').value.trim();if(!t){t='Thanks for showing up. Keep going.'}addEvent('cheer.add',{text:t}).then(ok=>{if(ok)$('cheerText').value='';})});\n$('graceButton').addEventListener('click',()=>{if(fold().graces[weekOf()+':'+actor])return;if(!confirm('Use your one grace day this week? It protects today in your momentum streak.'))return;addEvent('grace.use',{});});\n\n$('shareTop').addEventListener('click',()=>{tab='sync';render();document.querySelector('.tabs').scrollIntoView({behavior:'smooth'});});\n$('copyMyLink').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);notify('Private link copied. Keep it private.')}catch{prompt('Copy your personal private link:',location.href)}});\n$('refreshNow').addEventListener('click',()=>refreshGame());\nlet roomToken=null,roomUuid=null,refreshing=false;\nasync function cloudCall(body){\n if(!roomToken||!roomUuid)throw Error('Private link missing.');\n const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);\n try{const res=await fetch(location.pathname+'?api=1',{method:'POST',headers:{'content-type':'application/json'},cache:'no-store',body:JSON.stringify({...body,room:roomUuid,token:roomToken}),signal:controller.signal});\n const data=await res.json().catch(()=>({}));\n if(!res.ok||!data.ok)throw Error(data.error||('HTTP '+res.status));\n return data}finally{clearTimeout(timer)}\n}\nasync function refreshGame(){\n if(refreshing)return;refreshing=true;\n try{const d=await cloudCall({op:'state'});\n db.roomId=roomUuid;db.events=d.events;db.names=d.names;actor=d.actor;\n render();\n $('cloudConnection').textContent='Cloud connected · '+new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});\n $('roomStatus').textContent='Playing as '+name(actor)+' · '+db.events.length+' saved events · last sync '+new Date().toLocaleTimeString();\n }catch(err){$('cloudConnection').textContent='Offline / sync error';$('roomStatus').textContent='Could not refresh: '+err.message;notify('Room connection: '+err.message)}\n finally{refreshing=false}\n}\nfunction lockSeatControls(){\n document.querySelectorAll('[data-switch]').forEach(b=>{b.disabled=true;b.textContent=b.dataset.switch===actor?'Your seat':'Partner seat';});\n}\nconst gameRender=render;\nrender=()=>{gameRender();lockSeatControls()};\n(async()=>{const args=new URLSearchParams(location.hash.slice(1));roomUuid=args.get('room');roomToken=args.get('key');\n if(!/^[0-9a-f-]{36}$/i.test(roomUuid||'')||!/^[0-9a-f]{64}$/i.test(roomToken||'')){\n $('cloudConnection').textContent='Access link required';$('roomStatus').textContent='Open your personal invitation link with a room ID and private key.';tab='sync';render();return;}\n await refreshGame();\n setInterval(()=>{if(document.visibilityState==='visible')refreshGame()},15000);\n document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshGame()});\n})();\n</script>\n</body>\n</html>";
const SUPA_URL = Deno.env.get("SUPABASE_URL");
const LEGACY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
const SECRET = LEGACY || JSON.parse(Deno.env.get("SUPABASE_SECRET_KEYS") || "{}").default;
const HEADERS = {"apikey":SECRET, "Content-Type":"application/json", ...(LEGACY?{"Authorization":"Bearer "+LEGACY}:{})};
const reply=(v,s=200)=>new Response(JSON.stringify(v),{status:s,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff","referrer-policy":"no-referrer"}});
const failure=(s,msg)=>reply({ok:false,error:msg},s);
function validId(s){return typeof s==="string"&&/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(s)}
function text(s,max){return typeof s==="string"&&s.length<=max?s.trim():null}
const other=s=>s==="you"?"paula":"you";
function weekChicago(){
 const parts=Object.fromEntries(new Intl.DateTimeFormat("en-US",{timeZone:"America/Chicago",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date()).filter(p=>p.type!=="literal").map(p=>[p.type,p.value]));
 const d=new Date(Date.UTC(Number(parts.year),Number(parts.month)-1,Number(parts.day),12));
 const delta=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-delta);
 return d.toISOString().slice(0,10);
}
async function db(path,opts={}){
 if(!SUPA_URL||!SECRET)throw Error("Server database not configured");
 const res=await fetch(SUPA_URL+"/rest/v1/"+path,{...opts,headers:{...HEADERS,...opts.headers}});
 const body=await res.text();
 if(!res.ok)throw Error("Database request failed ("+res.status+")");
 return body?JSON.parse(body):null;
}
async function hashKey(k){const bytes=new TextEncoder().encode(k);const bytesHash=new Uint8Array(await crypto.subtle.digest("SHA-256",bytes));return [...bytesHash].map(x=>x.toString(16).padStart(2,"0")).join("")}
function fold(events){
 const quests={},stakes={},graces={},impacts={},witnesses={};
 for(const e of events){const d=e.data||{},w=e.week;
  switch(e.type){
   case "witness.link":witnesses[d.id]={...d,linkedBy:e.actor,withdrawn:false,reviews:[]};break;
   case "witness.review":if(witnesses[d.id]&&!witnesses[d.id].withdrawn)witnesses[d.id].reviews.push({actor:e.actor,mode:d.mode,note:d.note||""});break;
   case "witness.withdraw":if(witnesses[d.id])witnesses[d.id].withdrawn=true;break;
   case "quest.create":quests[d.id]={...d,status:"open",creator:e.actor};break;
   case "quest.edit":if(["open","needs_revision"].includes(quests[d.id]?.status))Object.assign(quests[d.id],d.changes);break;
   case "quest.remove":if(["open","needs_revision"].includes(quests[d.id]?.status))quests[d.id].removed=true;break;
   case "quest.submit":if(["open","needs_revision"].includes(quests[d.id]?.status)){Object.assign(quests[d.id],{status:"pending",submittedBy:e.actor,submittedAt:e.at,subjectDigest:d.subjectDigest||"",proof:d.proof||""})}break;
   case "quest.verify":if(quests[d.id]?.status==="pending")Object.assign(quests[d.id],{status:"done",verifiedBy:e.actor,verifiedAt:e.at,witnessMode:d.mode||"legacy",witnessNote:d.note||""});break;
   case "quest.refuse":if(quests[d.id]?.status==="pending")Object.assign(quests[d.id],{status:"needs_revision",refusedBy:e.actor,refusalReason:d.reason||""});break;
   case "impact.report":if(quests[d.id]?.status==="done")impacts[d.id]={...d,reporter:e.actor,review:null};break;
   case "impact.review":if(impacts[d.id])impacts[d.id].review={mode:d.mode,note:d.note||"",reviewer:e.actor};break;
   case "quest.reopen":if(quests[d.id]){delete impacts[d.id];Object.assign(quests[d.id],{status:"open",submittedBy:null,verifiedBy:null});}break;
   case "stake.propose":stakes[w]={id:d.id,proposer:e.actor,accepted:{[e.actor]:true}};break;
   case "stake.accept":if(stakes[w]?.id===d.id)stakes[w].accepted[e.actor]=true;break;
   case "grace.use":graces[w+":"+e.actor]=true;break;
  }
 }
 return {quests,stakes,graces,impacts,witnesses};
}
function checkEvent(type,data,actor,events,week){
 const invalid=(msg)=>{throw Error(msg)};
 const state=fold(events),q=state.quests[data.id];
 const str=(value,n)=>typeof value==="string"&&value.trim().length>0&&value.length<=n;
 const onlyId=()=>{if(!validId(data.id))invalid("Invalid quest identifier");return {id:data.id}};
 switch(type){
 case "witness.link":{
  if(!validId(data.id))invalid("Invalid bridge ID");
  if(!str(data.recordingId,200)||!/^[a-f0-9]{64}$/i.test(data.hash||""))invalid("Missing recording ID or audio digest");
  if(!str(data.passage,120)||!/^[-a-z0-9_.:]+$/i.test(data.passage)||!str(data.edition,100))invalid("Missing passage locator and edition");
  if(data.source!=="witness-package-v1")invalid("Wrong WITNESS source format");
  if(text(data.license||"",120)===null||text(data.recordedAt||"",64)===null)invalid("Bad recording provenance");
  if(Object.values(state.witnesses).some(x=>!x.withdrawn&&x.recordingId===data.recordingId&&x.hash===data.hash))invalid("Recording already linked");
  return {id:data.id,recordingId:data.recordingId,hash:data.hash.toLowerCase(),passage:data.passage.toLowerCase(),edition:data.edition,recordedAt:data.recordedAt||"",license:data.license||"",source:data.source};
 }
 case "witness.review":{
  if(!validId(data.id))invalid("Bad recording link ID");
  const w=state.witnesses[data.id];
  if(!w||w.withdrawn||w.linkedBy===actor||w.reviews.some(r=>r.actor===actor))invalid("Recording cannot be reviewed by this seat");
  if(!["heard","metadata"].includes(data.mode)||text(data.note||"",240)===null)invalid("Bad review basis");
  return {id:data.id,mode:data.mode,note:(data.note||"").trim()};
 }
 case "witness.withdraw":{
  if(!validId(data.id))invalid("Bad recording link ID");
  const w=state.witnesses[data.id];
  if(!w||w.linkedBy!==actor||w.withdrawn)invalid("Only the original linker can withdraw");
  return {id:data.id};
 }
 case "quest.create":{
  if(!validId(data.id)||state.quests[data.id])invalid("Duplicate or invalid quest ID");
  if(!str(data.title,140)||!["you","paula","both"].includes(data.owner)||![10,25,50].includes(data.xp))invalid("Quest fields invalid");
  if(!["FELLOWSHIP","HUMKIN","LIFE","OTHER"].includes(data.category))invalid("Quest category invalid");
  if(data.due&&(!/^20\d\d-\d\d-\d\d$/.test(data.due)))invalid("Invalid due date");
  if(text(data.notes||"",500)===null)invalid("Notes too long");
  return {id:data.id,title:data.title.trim(),owner:data.owner,xp:data.xp,category:data.category,due:data.due||"",notes:(data.notes||"").trim()};
 }
 case "quest.edit":{
  onlyId();if(!q||!["open","needs_revision"].includes(q.status)||q.removed)invalid("Cannot edit this quest");
  if(!(q.creator===actor||q.owner===actor||q.owner==="both"))invalid("Not your quest to edit");
  if(!str(data.changes?.title,140)||text(data.changes?.notes||"",500)===null)invalid("Quest changes invalid");
  return {id:data.id,changes:{title:data.changes.title.trim(),notes:(data.changes.notes||"").trim()}};
 }
 case "quest.remove":{
  onlyId();if(!q||!["open","needs_revision"].includes(q.status)||q.removed)invalid("Quest unavailable");
  if(!(q.creator===actor||q.owner===actor||q.owner==="both"))invalid("Not your quest to remove");
  return {id:data.id};
 }
 case "quest.submit":{
  onlyId();if(!q||q.removed||!["open","needs_revision"].includes(q.status)||!(q.owner===actor||q.owner==="both"))invalid("You cannot submit this quest");
  if(text(data.proof||"",500)===null)invalid("Proof note too long");
  return {id:data.id,proof:(data.proof||"").trim()};
 }
 case "quest.verify":{
  onlyId();if(!q||q.removed||q.status!=="pending"||q.submittedBy===actor)invalid("Only the other player may witness a pending quest");
  if(!q.subjectDigest||data.subjectDigest!==q.subjectDigest||!["observed","reviewed","trusted"].includes(data.mode)||text(data.note||"",240)===null)invalid("Witness encounter must cite the presented subject and precise basis");
  return {id:data.id,subjectDigest:q.subjectDigest,mode:data.mode,note:(data.note||"").trim()};
 }
 case "quest.refuse":{
  onlyId();if(!q||q.removed||q.status!=="pending"||q.submittedBy===actor||data.subjectDigest!==q.subjectDigest)invalid("Cannot refuse this subject");
  if(!str(data.reason,240))invalid("Refusal must specify what remains unverified");
  return {id:data.id,subjectDigest:q.subjectDigest,reason:data.reason.trim()};
 }
 case "impact.report":{
  onlyId();if(!q||q.removed||q.status!=="done"||q.submittedBy!==actor||state.impacts[data.id])invalid("Only the reporter may propose one consequence per confirmed quest");
  if(!str(data.after,240)||text(data.before||"",240)===null||text(data.beneficiary||"",120)===null)invalid("Consequence claim fields invalid");
  return {id:data.id,before:(data.before||"").trim(),after:data.after.trim(),beneficiary:(data.beneficiary||"").trim()};
 }
 case "impact.review":{
  onlyId();const imp=state.impacts[data.id];if(!q||q.status!=="done"||!imp||imp.reporter===actor||imp.review)invalid("This consequence cannot be reviewed by this player");
  if(!["reviewed","questioned"].includes(data.mode)||text(data.note||"",240)===null)invalid("Review evidence invalid");
  return {id:data.id,mode:data.mode,note:(data.note||"").trim()};
 }
 case "quest.reopen":{
  onlyId();if(!q||q.removed||q.status==="open")invalid("Quest is already open");
  if(q.status==="pending"&&q.submittedBy!==actor)invalid("Only the submitter can withdraw a pending quest");
  if(q.status==="needs_revision"&&q.submittedBy!==actor)invalid("Only the submitter can withdraw a refused quest");
  if(q.status==="done"&&q.verifiedBy!==actor)invalid("Only the witness can reopen a completed quest");
  return {id:data.id};
 }
 case "stake.propose":{
  const old=state.stakes[week];
  if(old?.accepted.you&&old?.accepted.paula)invalid("This week's pact is locked");
  if(!validId(data.id)||!["Meal","Favor","Money","Custom"].includes(data.kind)||!str(data.detail,180)||text(data.rule||"",180)===null)invalid("Stake details invalid");
  return {id:data.id,kind:data.kind,detail:data.detail.trim(),rule:(data.rule||"").trim()};
 }
 case "stake.accept":{
  if(!validId(data.id)||!state.stakes[week]||state.stakes[week].id!==data.id||state.stakes[week].proposer===actor||state.stakes[week].accepted[actor])invalid("Cannot accept this proposal");
  return {id:data.id};
 }
 case "grace.use":{
  if(state.graces[week+":"+actor])invalid("Grace already used this week");
  return {};
 }
 case "cheer.add":{
  if(!str(data.text,180))invalid("Write a short encouragement");
  return {text:data.text.trim()};
 }
 case "help.offer":{
  onlyId();if(!q||q.removed||q.status==="done"||q.owner===actor||q.owner==="both")invalid("Cannot offer help for this quest");
  return {id:data.id};
 }
 default:invalid("Unsupported event type");
 }
}
Deno.serve(async req=>{
 if(req.method==="GET")return new Response(HTML,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store","referrer-policy":"no-referrer","x-content-type-options":"nosniff","content-security-policy":"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; object-src 'none'; form-action 'none'"}});
 if(req.method!=="POST")return failure(405,"Unsupported method");
 try{
  const raw=await req.text();if(raw.length>6500)return failure(413,"Request too large");
  const reqBody=JSON.parse(raw);
  if(!validId(reqBody.room)||typeof reqBody.token!=="string"||!/^[a-f0-9]{64}$/i.test(reqBody.token))return failure(401,"A private invitation link is required");
  const keyHash=await hashKey(reqBody.token);
  const room=reqBody.room;
  const seats=await db("pact_v1_seats?select=seat,name&room_id=eq."+room+"&key_hash=eq."+keyHash+"&limit=1");
  if(!Array.isArray(seats)||seats.length!==1)return failure(401,"Private link not recognized");
  const actor=seats[0].seat;
  const records=await db("pact_v1_events?select=seq,id,actor,type,data,week,at&room_id=eq."+room+"&order=seq.asc&limit=900");
  const events=records.map(e=>({seq:e.seq,id:e.id,actor:e.actor,type:e.type,data:e.data,week:e.week,at:e.at}));
  if(reqBody.op==="state"){
   const peer=await db("pact_v1_seats?select=seat,name&room_id=eq."+room);
   const names={you:"Player 1",paula:"Paula"};for(const p of peer)names[p.seat]=p.name;
   return reply({ok:true,actor,names,events});
  }
  if(reqBody.op!=="event")return failure(400,"Unsupported operation");
  if(records.length>=800)return failure(409,"Room reached its initial 800-event limit; an archive upgrade is needed");
  if(records.filter(e=>e.actor===actor&&(Date.now()-Date.parse(e.at))<60_000).length>=24)return failure(429,"Too many changes in one minute");
  if(!validId(reqBody.id)||!reqBody.data||typeof reqBody.data!=="object"||Array.isArray(reqBody.data))return failure(400,"Invalid event payload");
  const week=weekChicago();
  let clean;
  try{clean=checkEvent(reqBody.type,reqBody.data,actor,events,week)}catch(e){return failure(409,e.message||"Action no longer valid")}
  if(reqBody.type==="quest.submit"){
    const q=fold(events).quests[clean.id];
    const exact=JSON.stringify(["static-collective.pact.subject.v1",room,clean.id,q.title,q.owner,q.notes||"",q.due||"",q.creator,actor,clean.proof]);
    clean.subjectDigest=await hashKey(exact);
  }
  await db("pact_v1_events",{method:"POST",headers:{"Prefer":"return=minimal"},body:JSON.stringify({id:reqBody.id,room_id:room,actor,type:reqBody.type,data:clean,week})});
  return reply({ok:true,saved:true});
 }catch(e){return failure(500,"Server unavailable or database error")}
});
